-- ============ 5. 对练剧本(5 剧本 × 3 轮,来源 mock.js#rolePlayScripts)============
INSERT INTO role_play_script (id, title, difficulty, persona, opening) VALUES
('s01', '只认保本的阿姨', '★★★☆☆', '62岁退休阿姨，认为"理财就是存款"，听说理财会亏钱后非常抗拒。', '小姑娘，你们这个理财产品是不是会亏本金的？我老伴儿说了，还是存银行定期踏实，你们就别给我推荐了。'),
('s02', '只看收益比高低的老板', '★★★★☆', '45岁个体批发商，手里有80万闲钱，开口就问"哪家收益最高"，流动性要求高。', '别跟我讲什么风险评级，我就问一句：哪家收益最高？我80万放你们这儿，比你同业低我可就去别家了。'),
('s03', '被套怕了的返乡青年', '★★★☆☆', '30岁返乡创业青年，去年买基金亏了15%，一朝被蛇咬，只肯把钱放活期。', '我去年买基金亏了15%，到现在还没回本。别再跟我提权益了，我的钱就放活期，亏是不会亏的，就是觉得有点亏得慌。'),
('s04', '被高息产品吸引的大妈', '★★★★☆', '58岁乡镇阿姨，被某平台8%高息理财吸引，风险意识薄弱，容易被误导。', '人家那个平台理财都给8个点，你们才3%不到，我为什么要买你们的？年轻人，你可得给我解释清楚。'),
('s05', '纠结党·永远在对比', '★★☆☆☆', '38岁中年客户，拿着五六家银行的方案反复对比，迟迟不做决定。', '你们这款产品我在另外两家银行也看到类似的，我再对比对比，你们这个业绩比较基准是能实现吗？别到时候又是广告。');

INSERT INTO script_round (script_id, round_no, question, keywords, tips, best_reply) VALUES
-- s01 只认保本的阿姨
('s01', 0, '客户表示"只存定期，理财会亏本金"', '["净值", "存款", "保障", "历史", "回撤", "稳", "存款保险"]', '先认同"求稳"心理，再用R2产品历史正收益数据对比存款利率下行的事实，切忌否定客户。', '阿姨您这个想法特别对，咱们求稳没错。其实定期利率这几年一直在降，三年期都不到2%了。像工银理财这款R2的产品，底层八成以上都是纯债，业绩比较基准3.15%，历史业绩稳健。您可以先拿一小部分试试水，和定期各放一半，比一比再说，好吗？'),
('s01', 1, '客户追问"万一亏了谁负责"', '["风险", "责任", "底层", "透明", "合同", "评级"]', '坦诚告知理财非保本，但解释风险评级、底层资产透明可查，并给出小额试水方案降低决策压力。', '阿姨，我实话实说，现在理财都是净值型，确实不承诺保本。但是您看它的风险评级是R2，也就是中低风险，底层资产是什么、占多少，说明书里写得清清楚楚，我一条条念给您听。咱们先投一万块，亏赚都看得见，您觉得踏实了再加，行不行？'),
('s01', 2, '客户说"回家跟老伴商量商量"', '["预约", "资料", "带上", "儿子", "一起", "下次", "方便"]', '不逼单，顺势留资，约定下次带老伴一起来，体现服务温度而非销售压迫感。', '应该的阿姨，这么大的事肯定要跟叔叔商量。这样，我把产品说明书和这份收益对比表留给您，回头您让儿子也帮您看看。咱们约下周三上午，您和叔叔一起来，我泡好茶等你们，再帮您算算具体的收益账，好不好？'),
-- s02 只看收益比高低的老板
('s02', 0, '客户只对比收益高低，不考虑风险', '["收益", "风险", "匹配", "底层", "波动", "同业", "对比"]', '不争最高收益，转而讲"收益可持续性"：拉长周期看最大回撤与年化稳定性，用同类对比数据说话。', '张老板，您这个思路我理解，做生意的都讲性价比。不过我给您个建议：看收益得连着风险一起看。标称收益高的产品底层多半重仓权益，行情一波动本金就要浮亏；您进货的钱随时要用，更适合收益稳定、随存随取的品种。咱们把收益、灵活性、风险放一张表里横向比，账不怕算细，您看好吗？'),
('s02', 1, '客户质疑"你们是不是在推销卖不掉的产品"', '["专业", "立场", "透明", "数据", "合作", "信任", "替您"]', '亮明专业立场，用第三方数据佐证，强调"替您管钱"的顾问身份，建立信任。', '张老板，您这话问得直接，我也答得直接：工银、杭银、兴银、渝农商四家理财子我都有代销权，我挑产品只看两条——底层透不透明、和您的资金用途合不合。您要不放心，咱们把四家的产品放在一张表里横向比，收益、期限、底层，一目了然。我是替您管钱的人，不是替某一家卖货的人，这个立场您随时可以检验。'),
('s02', 2, '客户要求"收益不达标就撤资"的口头承诺', '["合规", "承诺", "不能", "监管", "规则", "底线", "服务"]', '坚守合规底线，不承诺收益；把话题引导到服务与信息透明上，用专业性代替违规承诺。', '张老板，任何承诺收益的话都是违规的，我不说您也不爱听虚的。我能承诺的是三件事：第一，每周给您推送净值和收益数据；第二，底层资产有变化第一时间同步；第三，有更优的同业产品随时如实比给您。钱交不交、什么时候撤，决定权始终在您手里，我挣的是专业透明的口碑。'),
-- s03 被套怕了的返乡青年
('s03', 0, '客户因历史亏损对投资极度恐惧', '["理解", "共情", "仓位", "小步", "起步", "回本", "经历"]', '先共情再引导，肯定"亏得慌"的感受，用"先管活钱、再谈增值"两步法降低心理门槛。', '您这个感受我特别理解，亏15%搁谁身上都难受，说明您其实很在意自己的钱，这不是坏事。咱们不急着谈权益，先把活期里的钱管起来：像兴银这款现金管理产品，随存随取T+1到账、灵活性和活期一样，业绩比较基准却有2.05%，一年下来几万块也能多出小几百。先让钱不闲着，等您感觉踏实了，我们再聊下一步，您看行吗？'),
('s03', 1, '客户问"那要怎么才能回本"', '["纪律", "定投", "时间", "摊薄", "回本", "仓位", "科学"]', '不承诺回本，讲清"科学补仓与纪律"：小比例固收+起步、定投摊薄成本，强调时间与纪律而非预测。', '说实话，回本这件事没有人能打包票，但我可以告诉您怎么让回本的概率变大：一是别一次重仓，用定投的方式摊薄成本；二是把大部分资金放在R2的固收+上稳稳打底，用小部分资金小步参与，亏了不伤元气，赚了能修复整体收益。您去年亏15%，很大程度上是因为仓位太重了，对吗？'),
('s03', 2, '客户仍然犹豫"要不还是再等等"', '["机会", "成本", "今天", "一点", "试", "不急", "自主"]', '尊重客户决定权，用"机会成本"轻推一把，给出当天可完成的最小动作，留好下次触点。', '不急，钱是您的，节奏也该由您定。我只提醒一个成本：活期趴着每天的机会成本大概相当于一杯豆浆钱，一年下来小一千。要不这样，今天不用做任何决定，您先开通理财账户，我帮您留一份现金管理类产品的资料，您想清楚了随时找我，哪怕就投100块试个水也行，主动权都在您手里。'),
-- s04 被高息产品吸引的大妈
('s04', 0, '客户被明显不合理的高息产品吸引', '["8%", "高", "不正常", "风险", "底层", "警惕", "对照", "常识"]', '不贬低对手，用常识对比引导思考：高于市场均值太多的收益必然伴随看不见的风险，提醒核实底层与资质。', '阿姨，8%这个数字确实诱人，咱们一起用常识算笔账：现在国债才2%左右，银行间借钱的成本也就2%上下，一个产品稳定给8%，那它得把钱借给什么人才能付得起这么高的利息呢？我不是说它一定有问题，但您买之前一定要问清楚两件事：钱借给了谁、有没有正规金融牌照。您把产品名字发我，我帮您一起看看底层。'),
('s04', 1, '客户反驳"我邻居都买了好几年都没事"', '["幸存者", "个例", "几年", "暴雷", "出事", "本金", "先例"]', '用"幸存者偏差"讲清个例≠安全，引用过往高息平台爆雷案例提醒，不引起对立。', '阿姨，邻居没出事我真心为她高兴，但您发现没有，出事的人是不会到处说的。前几年那些年化10%以上的平台，出事前个个都"好几年没事"，最后一夜之间本金就没了。投资这件事，宁可收益慢一点，也要睡得着觉。您这养老钱，经不起一次归零的风险，对吗？'),
('s04', 2, '客户试探"那你保证你们的产品不亏？"', '["不承诺", "合规", "实话", "诚实", "透明", "历史", "评级"]', '绝不违规承诺，反而以"说真话"建立信任，用历史数据与风险评级给出有边界的安心感。', '阿姨，我要是跟您说"保证不亏"，那我就跟外面卖8%的是一个套路了。我跟您说真话：所有理财都不保本，但是分风险等级。您适合看R1、R2的，底层是债券和存款，历史业绩稳健，波动很小。愿意对您说实话的人，和愿意把高息捧到您面前的人，您更需要哪一个？'),
-- s05 纠结党·永远在对比
('s05', 0, '客户质疑业绩比较基准"只是广告数字"', '["基准", "含义", "历史", "达标", "解释", "数据", "不是承诺"]', '耐心科普业绩比较基准的准确定义，用历史达标数据回应，体现专业而不回避。', '您问到点子上了，业绩比较基准确实不是承诺收益，它是管理人基于策略给出的"考卷目标分"。咱们看实际表现：这款产品过去8个季度，绝大多数季度实际年化都跑在基准区间附近，同类排名靠前。我把历史净值明细拉给您，一个季度一个季度对，比听我说是多少都实在，您看可以吗？'),
('s05', 1, '客户展示别家方案要求"同样条款"', '["横向", "对比", "差异", "优势", "底层", "回撤", "透明", "开放"]', '欢迎对比、主动做横向比较表，突出差异化优势（起购门槛/流动性/底层结构），而不是贬低同业。', '非常欢迎对比，比得越细您越踏实。我直接给您做一张四家理财子的横向对比表：业绩比较基准、风险等级、期限、起购门槛、底层资产，几列放一起。咱们家这款优势在100元起购加底层纯债，别家收益可能略高，但要么起购门槛高、要么期限长不灵活。您拿着这张表去比，比完我还在，这就是底气。'),
('s05', 2, '客户说"我再想想，下周再说吧"', '["名额", "建议", "今天", "部分", "建仓", "不催", "决定", "时间"]', '不催单，制造合理稀缺或分步动作，把"全投"降级为"先建底仓"，保留决定权的同时推进落袋。', '可以，决定不着急做，但有个信息同步给您：这一期募集到这周五截止，下期开放要等一个月，中间空档的收益就错过了。要不咱们不追求"全投"，今天先投一小部分把底仓建起来，剩下的等您想明白了随时加？不催您大决定，只帮您不空档，您看这样安排合理吗？');

