INSERT INTO mot_event (event_date, event_time, type, client_name, client_tag, event_title, detail, ai_strategy, generated_script, phone, customer_no, assets, risk, traits, touch) VALUES
(CURDATE(), '09:00', 'maturity', '王老板', '建材城批发商 | 资产500W+', '【300万大额存单明日到期】', '大额存单 300万 · 明日到期，当日为资金承接黄金窗口', '客户对资金灵活性要求高，且近期无大额采购计划。建议用"四笔钱"逻辑，推荐【兴银现金日盈】承接100万流动资金，【工银核心优选】锁定200万中期稳健收益。', '王总早上好！您行里那笔300万的存单明天就到期啦。最近降息快，我帮您盯了两款特别适合您的替代产品：一款是兴银的现金理财，100万放里面随存随取，完全不耽误您进货；剩下的帮您锁定工银的稳健产品，比放活期划算得多。您看要不要先过来喝杯茶，我给您详细测算下？', '138 6688 2391', 'SCRC20260001', '资产 500W+', '中低风险 R2', '资金周转频繁，重灵活性；历史仅购买过大额存单，无在途权益仓位', '白天忙生意，上午 9 点与晚上 8 点后接听率最高'),
(CURDATE(), '11:30', 'behavior', '李大姐', '保守型储户 | 资产80W', '【高频浏览理财产品】', '昨晚 21:00-23:00 连续 3 次浏览【杭银幸福99】，累计停留 11 分钟', '客户昨晚连续3次浏览【杭银幸福99】，停留超过3分钟。客户风险偏好低，但对收益有期待，正在犹豫。建议重点强调杭银的历史业绩和固收+底仓。', '李姐中午好，吃饭没呢？最近看您在关注理财，是想找收益稍微好一点的对吧？杭银那款确实不错，它是同业里的"优等生"，大部分钱投在最稳妥的债券里，拿了一小部分去打新股赚超额收益。其实您可以先拿5万块钱试试水，我随时帮您盯着净值，您觉得行不？', '139 2233 5876', 'SCRC20260002', '资产 80W', '稳健型 R2', '近三个月登录 APP 21 次，理财页浏览时长持续上升；曾因基金亏损到店咨询 3 次', '对"被推销"敏感，宜用关怀式开场，午休 12:00-13:30 较合适'),
(CURDATE(), '14:00', 'alert', '张建国', '返乡创业青年 | 资产120W', '【持有产品净值连续回撤】', '持有【渝农商益农稳健】120万，近一周回撤 0.15%，赎回风险上升', '客户持有的【渝农商益农稳健】近一周回撤0.15%。需主动安抚，避免客户恐慌赎回，解释债市波动宏观原因。', '建国，最近是不是看理财账户有点绿，心里打鼓啦？别慌，这两天宏观资金面有点紧，整个债市都在回调，咱们买的渝农商这款也不例外。但它的底层资产都是真材实料的优质债券，只要不现在割肉赎回，把期限拿满，后面的票息收益是能覆盖掉现在的波动的。把它当成一次"倒车接人"就好啦。', '187 9755 4102', 'SCRC20260003', '资产 120W', '平衡型 R3', '持有【渝农商益农稳健】120 万；对债市知识感兴趣，学习意愿强', '语气朋友化，先安抚情绪再讲逻辑，建议晚间 20:00 后联系');
